exercises.solution:
def grade(score):
    if not 0 <= score <= 100:
        raise ValueError("score must be between 0 and 100")
    if score >= 90:
        return "A"
    if score >= 80:
        return "B"
    if score >= 70:
        return "C"
    if score >= 60:
        return "D"
    return "F"

def sum_to(n):
    total = 0
    for value in range(1, n + 1):
        total += value
    return total

def fizzbuzz(n):
    out = []
    for value in range(1, n + 1):
        if value % 15 == 0:
            out.append("FizzBuzz")
        elif value % 3 == 0:
            out.append("Fizz")
        elif value % 5 == 0:
            out.append("Buzz")
        else:
            out.append(value)
    return out

def second_largest(numbers):
    distinct = sorted(set(numbers))
    if len(distinct) < 2:
        return None
    return distinct[-2]

def middle_three(text):
    if len(text) < 3 or len(text) % 2 == 0:
        return ""
    middle = len(text) // 2
    return text[middle - 1:middle + 2]

def word_count(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

