def lookup(data, key, default=None):
    if key in data:
        return data[key]
    return default

def unique(items):
    seen = set()
    out = []
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out

def by_surname(names):
    def key(name):
        first, _, last = name.rpartition(" ")
        return (last, first)
    return sorted(names, key=key)

def top_n(scores, n):
    ordered = sorted(scores.items(), key=lambda pair: (-pair[1], pair[0]))
    return [name for name, _score in ordered[:n]]

def totals(rows):
    out = {}
    for row in rows:
        key = row["category"]
        out[key] = out.get(key, 0) + row["amount"]
    return out

def add_item(item, basket=None):
    if basket is None:
        basket = []
    basket.append(item)
    return basket

def describe(*values, **options):
    head = f"{len(values)} values"
    if not options:
        return head
    tail = " ".join(f"{k}={options[k]}" for k in sorted(options))
    return f"{head} | {tail}"

