def count_collisions(keys, buckets):
    if buckets < 1:
        raise ValueError("buckets must be at least 1")
    seen = set()
    used = set()
    collisions = 0
    for key in keys:
        if key in seen:
            continue
        seen.add(key)
        bucket = key % buckets
        if bucket in used:
            collisions += 1
        else:
            used.add(bucket)
    return collisions

def heap_violation(values):
    for i in range(1, len(values)):
        if values[i] < values[(i - 1) // 2]:
            return i
    return None

def balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

