def order(tasks):
    pending = {name: set(deps) for name, deps in tasks.items()}
    out = []
    while pending:
        ready = sorted(n for n, deps in pending.items()
                       if not (deps & pending.keys()))
        if not ready:
            raise ValueError("dependency cycle")
        for name in ready:
            out.append(name)
            del pending[name]
    return out

