class OverBudget(BaseException):
    pass
class Counted(list):
    spent = 0
    budget = 0
    def spend(self, reads):
        Counted.spent += reads
        if Counted.spent > Counted.budget:
            raise OverBudget
    def __iter__(self):
        for value in list.__iter__(self):
            self.spend(1)
            yield value
    def __getitem__(self, index):
        if isinstance(index, slice):
            part = Counted(list.__getitem__(self, index))
            self.spend(len(part))
