import itertools


def chunk_totals(rows, size):
    if size < 1:
        raise ValueError("size must be at least 1")
    # itertools.batched does this on 3.12+; islice works on 3.11 too.
    it = iter(rows)
    while chunk := list(itertools.islice(it, size)):
        totals = {}
        for key, amount in chunk:
            totals[key] = totals.get(key, 0) + amount
        yield totals


def grand_total(rows, size):
    merged = {}
    for totals in chunk_totals(rows, size):
        for key, amount in totals.items():
            merged[key] = merged.get(key, 0) + amount
    return merged

def group_totals(rows, key, value):
    out = {}
    for row in rows:
        if row[value] is None:
            continue
        group = row[key]
        out[group] = out.get(group, 0) + row[value]
    return out

