def newton(f, df, x0, tol=1e-12, max_iter=50):
    x = x0
    for _ in range(max_iter):
        slope = df(x)
        if slope == 0:
            raise ValueError("zero derivative")
        nxt = x - f(x) / slope
        if abs(nxt - x) < tol:
            return nxt
        x = nxt
    raise ValueError("did not converge")

