class Outbox:
    def __init__(self, capacity):
        self.items = deque(maxlen=capacity)
        self.capacity = capacity
        self.dropped = 0

    def add(self, reading):
        if len(self.items) == self.capacity:
            self.dropped += 1
        self.items.append(reading)

    def flush(self, send):
        sent = 0
        while self.items:
            if not send(self.items[0]):
                break
            self.items.popleft()
            sent += 1
        return sent

